// F-03 domain rules (pure functions, no database) — contract docs/sprints/sprint-2/F-03-teams.md §2.
// Join codes are generated by the SQL function cpms_join_code() (migration f03_team_formation, T7).

export const JOIN_CODE_PATTERN = /^[A-HJ-NP-Z2-9]{8}$/;
export const LIMITS = { name: 60 };

/** FR-10: team name required, trimmed, 1–60 characters. Only `name` is read from the body (T9). */
export function validateTeamName(body) {
  const name = body?.name;
  if (typeof name !== 'string' || !name.trim()) return { ok: false, details: { name: 'Team name is required' } };
  const trimmed = name.trim();
  if (trimmed.length > LIMITS.name) return { ok: false, details: { name: `Team name must be at most ${LIMITS.name} characters` } };
  return { ok: true, value: { name: trimmed } };
}

/** T7: codes are compared after trim + upper case; anything else than 8 allowed characters is malformed. */
export function normalizeJoinCode(body) {
  const raw = body?.joinCode;
  const code = typeof raw === 'string' ? raw.trim().toUpperCase() : '';
  if (!JOIN_CODE_PATTERN.test(code)) {
    return { ok: false, details: { joinCode: 'Join code must be 8 letters or digits (no O, I, 0 or 1)' } };
  }
  return { ok: true, value: code };
}

/** BR-07 (join): there must be a free place. Joining as the maxTeamSize-th member is allowed. */
export function canJoin(memberCount, maxTeamSize) {
  return memberCount < maxTeamSize;
}

/** BR-07 (submit): a proposal can be submitted only with at least minTeamSize members. */
export function hasMinimumSize(memberCount, minTeamSize) {
  return memberCount >= minTeamSize;
}

/** BR-08: membership is locked once any proposal of the team is APPROVED. */
export function isMembershipLocked(proposalStatuses) {
  return proposalStatuses.includes('APPROVED');
}
